@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'Gift Card  Details'
@Metadata.ignorePropagatedAnnotations: true
define view entity ZLH_R_TRANSACTIONS as select from zlh_transactions
association to parent ZLH_R_BusinessPartner as _BP on $projection.BusinessPartner = _BP.SoldToParty
{
  key transaction_id as TransactionId,
  business_partner as BusinessPartner,
  membershipid as Membershipid,
  ref_salesorder_id as RefSalesorderId,
  activity_type as ActivityType,
  @Semantics.amount.currencyCode : 'TransactionCurrency'
  transaction_amount as TransactionAmount,
  transaction_currency as TransactionCurrency,
  loyalty_points as LoyaltyPoints,
   case
        when activity_type =  'Promotion' then 3
        when activity_type =  'Redemption' then 1
        when activity_type =  'Accrual' then 3
        when activity_type =  'Bonus' then 3
        when activity_type =  'Purchase' then 3
        else 1
      end as ActivityCriticality,
       case
        when activity_type =  'Promotion' then  concat('+ ', cast(loyalty_points as abap.char(20)))
        when activity_type =  'Redemption' then  concat('- ', cast(loyalty_points as abap.char(20)))
        when activity_type =  'Accrual' then  concat('+ ', cast(loyalty_points as abap.char(20)))
        when activity_type =  'Bonus' then  concat('+ ', cast(loyalty_points as abap.char(20)))
        when activity_type =  'Purchase' then  concat('+ ', cast(loyalty_points as abap.char(20)))
        else concat('- ', cast(loyalty_points as abap.char(20) ))
      end as FormatedLoyaltyPoints,
  @Semantics.user.createdBy: true
  created_by as CreatedBy,
//  @Semantics.systemDateTime.createdAt: true
  created_on       as CreatedOn,
  transaction_date as TransactionDate,
//  @Semantics.systemDateTime.lastChangedAt: true
  last_changedat as LastChangedat,
  @Semantics.user.lastChangedBy: true
  last_changedby as LastChangedby,
  point_expiry_date as PointExpiryDate,
  _BP
}
